insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4cbdb881-da9c-47a5-bedb-19e0456a3896', 'ja', '触れることを、強引ではなく、効果的に感じさせるものは何ですか？', '["彼女の心地よさと、築いてきた打ち解け具合に合っていること", "短く軽いこと。長引いたり、重かったりしないこと", "笑っているときや、話の要点を伝えるときなど、自然な瞬間であること", "上のすべて"]'::jsonb, '触れることが心地よく感じられるのは、打ち解け具合に合っていて、軽いままで、自然な瞬間に起こるときです。')
