insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f400953-0471-468b-911c-2009c87a96ac', 'ja', '会話は楽しく、彼女は笑っています。そして、自然に立ち去ります。どう考えるべきですか？', '["LINEを交換できなかったから、失敗だった", "やり取りが短すぎたから、失敗だった", "二人ともその時間を楽しんだから、成功だった"]'::jsonb, 'その先がどうであれ、目指すのは、二人で分かち合う前向きな時間です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50183c21-27bd-480c-971a-891eac026c00', 'ja', '彼女が「男の人は、いつも飲み物をおごってくれるんです」と言います。簡単にはなびかない返しとして、次に何と言えますか？', '["「次の一杯をおごってくれるなら」", "「じゃあ、一杯ごちそうさせてください」", "「わかります。魅力的ですから」", "「好きな飲み物は何ですか？」"]'::jsonb, '無条件に合わせる代わりに、遊び心を込めて挑むことで、釣り合いと楽しさが保たれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51566fba-0f2e-472b-9786-baa55e298382', 'ja', '触れることを、踏み込まれた感じではなく、自然に感じさせるものは何ですか？', '["何度も繰り返すこと", "気持ちの温かい瞬間に起こること", "短く、軽いこと", "彼女の心地よさの度合いに合っていること"]'::jsonb, '回数の多さや強さは、相手を圧倒します。タイミングと、相手に合わせることが、心地よさを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51c9bf97-c01a-4148-8ca9-32bec583870d', 'ja', '彼女が「私、いつも進みの遅い列を選んでしまうんです」と言います。次に何と言えますか？', '["「ええ、誰にでもあることですよ」", "「どうしてそう思うんですか？」", "「この列も遅いですね」", "「それはもう、呪われていますね。運を上げたいなら、こちらのそばにいてください」"]'::jsonb, '温かみのある大げさな言い方は、いたずら心を足し、遊び心のあるリズムを開きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530e8449-212d-45aa-8e97-70907690cac7', 'ja', '恋愛的な含みのある伝え方を生むものは、何ですか？', '["ゆっくりしたペース。急がないこと", "話しながら、目を合わせたままでいること", "小さな間を置いて、言葉が届くのを待つこと", "上のすべて"]'::jsonb, '駆け引きは、ペースと、その場にいる姿勢から生まれます。ゆっくり話し、目を合わせたまま、言葉が届くのを待ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('545da6d1-d1bc-41b2-90a4-6fb6c5a2003c', 'ja', '駆け引きにおける「アイコンタクト」とは、何ですか？', '["会話のあいだずっと、しっかり目を合わせ続けること", "緊張感を生み、関心を伝えるための、意図のある視線", "自信を示すために、彼女の目を深く見つめること"]'::jsonb, '駆け引きにおけるアイコンタクトは、支配ややりすぎではなく、その場にいる姿勢を通じて、関心を伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('56839c41-b051-44d1-8c8b-3c1fc53a0809', 'ja', '彼女が、複雑な話題を説明してくれます。一番よく届く褒め言葉は、どれですか？', '["「すごくわかりやすく説明してくれましたね。ついていきやすかったです」", "「本当にきれいですね」", "「頭が良さそうですね」", "「声がすごくいいですね」"]'::jsonb, '彼女の選択と努力に絞った言葉で、その進め方を本当に見ていたことが伝わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('57ea4716-3a0a-4ae1-9b73-029195409a88', 'ja', '小さく一歩近づいても、彼女は会話に乗ったままです。これは何を示していますか？', '["青信号。距離が縮まっても、彼女は心地よく感じている", "すぐに、もっとスペースを求めている", "安全のために、一歩下がるべきだ", "やり取りは、まだ早すぎる段階にある"]'::jsonb, 'その場にとどまったり、同じように返してきたりするのは、近い距離を心地よく感じているサインです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6021e5f1-ba61-4cb2-82c5-d1977fcb9ef6', 'ja', '彼女は静かなカフェで、リラックスして、小さな声で話しています。こちらのエネルギーは、何に合わせるべきですか？', '["温かいトーンで、リラックスして落ち着いたエネルギー", "彼女を元気づける、高くて生き生きしたエネルギー", "無頓着に見せるための、だるそうで疲れたエネルギー", "周りの音に負けない、大きな声"]'::jsonb, '彼女のリラックスした気分に合わせて、二人で分かち合える心地よさをつくりましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('634ce3b6-9096-4656-87e7-87d80d609efd', 'ja', '彼女が、こちらの目を深く見つめて、ひとつの瞬間をつくります。見つめ返すことは、何を示しますか？', '["意図のある関心と、関係を変えたいという気持ち", "礼儀正しくしているだけ", "緊張と居心地の悪さ"]'::jsonb, '落ち着いた視線は、恋愛的な意図を、言葉なしに伝えます。')
