insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63ef4906-b21c-4006-a7c2-c6651684dc24', 'ja', '届く褒め言葉と、空振りに終わる褒め言葉を分けるものは何ですか？', '["具体的で、本心からで、彼女が選んだことをよく見たものであること", "彼女をほかの人と分ける、独自の資質に目を向けていること", "下心のない、誠実で心のこもったものであること", "上のすべて"]'::jsonb, '褒め言葉が届くのは、具体的で、本心からで、彼女が選んだことに結びついているときです。')
