insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6581dc47-ce07-4d7a-a3fb-126a6b812a79', 'ja', 'いたずら心を伝えるとき、なぜ温かさが大切なのですか？', '["温かさが、いたずら心を、本当の無礼に感じさせないから", "言葉が明瞭になり、冗談が正しく理解されるから", "温かさがあると、人は会話をよく覚えているから"]'::jsonb, '温かさが、いたずらっぽいひと言を、遊びとして伝えます。それがなければ、同じ言葉が無礼に感じられることもあります。')
