insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('67aef6c5-f235-4eb5-ad2b-86fb824c4b0a', 'ja', '会話の中で、彼女の個性的なスタイルに気づきます。一番良い褒め方はどれですか？', '["「いいスタイルですね！」とさっと言って、次に進む", "もっと大胆な言葉を使う", "目を合わせずに、ありきたりに褒める", "声をやわらげ、目を合わせて、「そのスタイル、すごく目を引きますね」と言う"]'::jsonb, '礼儀としてさっと言うよりも、温かさを込めて、ていねいに伝えるほうが、惹かれる気持ちを育てます。')
