insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71303602-cef7-48f0-9a80-8ba290228313', 'ja', '目を合わせ続けることは、何をもたらしますか？', '["言葉を超えた緊張感を、二人のあいだに生む", "言葉にせずに、関心を伝える", "人付き合いでの自信を示す"]'::jsonb, 'アイコンタクトは、反応を無理強いすることなく、言葉を使わずに関心を伝えます。')
