insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('897a30cf-cd54-4901-b729-6b351f07085b', 'ja', '彼女が「私、決めるのがすごく苦手なんです」と言います。どういたずら心を使えますか？', '["「大丈夫ですよ。完璧な人なんていませんから」", "「いつもは、何が決め手になるんですか？」", "「何でもいいから選んでください。大丈夫ですよ」", "「じゃあ、メニューが怖いんですね？」"]'::jsonb, '軽くいたずらっぽい大げさな言い方は、笑いと、遊び心のある返しを招きます。')
