insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8b46401f-6a8e-4626-a152-9b226dc2e7bf', 'ja', '良い雰囲気を感じていますが、ためらっています。待ちすぎると、どんなリスクが生まれますか？', '["関心がないと、彼女に思われるかもしれない", "やり取りが、礼儀正しく、どちらともつかないままになる", "緊張感が生まれる自然なタイミングを逃す", "上のすべて"]'::jsonb, 'こうした瞬間は、時間が限られています。チャンスは短いけれど、意味のあるものです。')
