insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b2a1ba-b2aa-42e8-bf7a-d35951d81430', 'ja', 'バーで、にぎやかなグループに声をかけようとしています。どんなエネルギーがうまくいきますか？', '["相手のにぎやかさと釣り合うように、リラックスした落ち着いたエネルギーを持ち込む", "明るいトーンで、相手のにぎやかなエネルギーに合わせる", "良い意味で目立つように、相手のエネルギーを少し上回る"]'::jsonb, '人は、自分たちのリズムに合った、明るいエネルギーに一番よく応えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95247c9b-621b-4050-bfa2-a28902ab1b90', 'ja', '軽い勝負は、なぜふつうの会話よりも速く相性の良さを育てるのですか？', '["小さな緊張感と、気持ちの入り方を生むから", "知らない人同士を、ひとときのライバルやチームメイトに変えるから", "彼女の積極的な参加が必要になるから", "上のすべて"]'::jsonb, '遊びの賭けは、本当のプレッシャーなしに、エネルギーと関わりに火をつけます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1c414f9-7ab4-4475-a07e-69d6eb6b1ba4', 'ja', '彼女が、チェスが好きだと冗談めかして言います。駆け引きになる返しとして、何と言えますか？', '["「チェスは、すごく難しいですよね」", "「チェスは、ずいぶん簡単な競技ですよね」", "「競争は、体に良くないですよ」", "「クイーンの守り方なら、心得ていますよ」"]'::jsonb, '彼女の遊び心に合わせて、軽い掛け合いとエネルギーを盛り上げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a25d7cd3-3b21-4ccb-89ba-1cffbbe6a49d', 'ja', '軽い掛け合いは、なぜ恋愛的な相性を育てるのに役立つのですか？', '["気楽な緊張感と遊び心を生むから", "笑いを通じて、気持ちの距離を縮めるから", "会話を、まじめで礼儀正しいままに保つから", "返し合うやり取りのエネルギーを持ち込むから"]'::jsonb, '遊び心が、駆け引きを、ただの感じのいい打ち解けた空気と分けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2f4b225-b8a7-4317-8f9e-d5d7ce3e0c73', 'ja', '相手を尊重した気づかいを示す行動は、どれですか？', '["彼女の気を変えさせるために、会話を続けること", "「彼氏がいます」という言葉を、詮索せずに受け入れること", "彼女の返事が短いとき、一歩引くこと", "会話に乗っていないとき、礼儀正しくやり取りを終えること"]'::jsonb, '尊重とは、関心がないときに、どれだけ早く合わせ直し、どれだけすっきり立ち去れるかです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a621c77a-69b0-4f0a-8e2f-6e12dbf8bc0b', 'ja', '簡単にはなびかない姿勢は、なぜ惹かれる気持ちを生むのですか？', '["彼女の承認を追いかけていることを示すから", "無条件に同意するパターンを破るから", "彼女を持ち上げすぎるのではなく、対等な相手として扱うから"]'::jsonb, '簡単にはなびかない姿勢は、追いかける形を、釣り合いの取れた、お互いに選び合う形へとひっくり返します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a64d80aa-89d6-4008-bb0c-2e3f3d44e8d8', 'ja', '性的な緊張感の「火花」を生むものは、何ですか？', '["友達以上なのかどうかについての、かすかな不確かさ", "すべてを、先が読めて感じのいいままに保つこと", "早い段階で、恋愛的な意図をはっきり述べること", "体の存在を、いっさい意識しないようにすること"]'::jsonb, '「これは、それ以上の何かなのだろうか」という問いが、注意を引きつけ続けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a9af130c-ceeb-430c-817a-3b39ec63ff4b', 'ja', '駆け引きにおける軽い勝負を、最もよく表しているのはどれですか？', '["何の結果も伴わずに、関わりを生む遊び心のあるやり取り", "彼女がどれだけ賢いか、腕があるかを見るためのテスト", "彼女を困らせるための、からかいの一種"]'::jsonb, '軽い勝負は、二人で分かち合う、害のない遊びです。本当にかかっているものは、何もありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ac1764e4-0635-4b2a-a9b1-3d396b43c335', 'ja', '少しだけ近づいても大丈夫だと示すサインは、どれですか？', '["一歩近づいても、彼女がリラックスしたままでいる", "話しながら、身を寄せてくる", "目を合わせたままでいる", "何度も部屋を見回す"]'::jsonb, '心地よさは、その場にとどまること、同じように返してくること、リラックスした関わり方に表れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('af902d35-dd20-4ecf-9ebd-6cc05bed06fb', 'ja', '性的な緊張感のために、打ち解けた空気を破ることがなぜ必要なのですか？', '["打ち解けた空気だけでは、やり取りが友達どまりで、先の読めるものになるから", "空気を破ることで、「恋愛の可能性はあるのか」という問いが生まれるから", "途切れない打ち解けた空気は、いつでも惹かれる気持ちを高めるから"]'::jsonb, '緊張感は、友達以上の何かをにじませることから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b39a64ab-2d91-47b4-9ea1-8646ba10c538', 'ja', '触れることをいっさい避けると、なぜ惹かれる気持ちが育たなくなることが多いのですか？', '["退屈に感じられるから", "やり取りが、友達同士のものに感じられるから", "自信のなさを示すから", "会話のペースを落とすから"]'::jsonb, '体の面で距離が縮まらないと、やり取りは、恋愛的な含みのあるものではなく、感じのいいもののままになることがあります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4ae1063-f21b-4c92-b4e9-ddeb53c5685f', 'ja', '彼女が、話しながらバーカウンターにもたれます。どうミラーリングできますか？', '["自信を示すために、固まったままでいる", "すぐに、彼女とまったく同じ姿勢をまねる", "距離を縮めるために、一歩近づく", "少しずつ、似たようなリラックスした姿勢を取る"]'::jsonb, 'さりげなくそろえることで、わざとらしさなしに、安心感が育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b4cb96a5-9dac-4da8-9559-0e356ea4eeeb', 'ja', '相手に合わせたタッチは、なぜ効果的に惹かれる気持ちを育てるのですか？', '["恋愛的な関心を、言葉を使わずに伝えるから", "すでにあるつながりに、体の面での層を加えるから", "大胆で、回数が多いときに一番うまくいくから"]'::jsonb, '意図のあるタッチは、彼女が心地よく感じているタイミングに合っているとき、相性の良さを強めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5aafcca-ae9a-48c1-974b-435701916b85', 'ja', '彼女が、地図を読むのがすごく得意だと言います。駆け引きになる返しは、どれですか？', '["「じゃあ、その心への道順も、教えてもらえますか？」", "「地図アプリを、もっと使ったほうがいいんじゃないですか」", "「それは、うぬぼれですね（笑）」", "「道案内なんて、そんなに難しくないですよ」"]'::jsonb, '駆け引きのユーモアは、彼女の言葉に遊び心を込めて乗ることで、惹かれる気持ちを育てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b60b077a-0761-4330-9234-8fdcc1b81325', 'ja', '体のミラーリングは、なぜ無意識のレベルで打ち解けた空気を育てるのですか？', '["脳が、そろったボディランゲージを、安全で、なじみがあり、信頼できるものとして受け取るから", "注意を払っていて、彼女に関わっていることを示すから", "人付き合いのうまさと、感情への気づきを示すから"]'::jsonb, 'ミラーリングは、無意識のレベルで、親しみと心地よさを伝え、打ち解けるのを助けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b70c5e9d-c782-4a54-be4f-ed860758730b', 'ja', '一番良い褒め言葉は、どんな種類のものですか？', '["彼女のスタイル、ユーモア、彼女ならではの見方に向けたもの", "努力や、物事への関わり方に向けたもの", "生まれ持ったものではなく、彼女が選んだり表現したりしたことに向けたもの", "上のすべて"]'::jsonb, '褒め言葉は、生まれ持った特徴ではなく、彼女が選んだことに向けられたとき、一番よく届きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc66a400-41a9-4f56-9e78-344908ee749c', 'ja', '触れることは、なぜ言葉だけの場合よりも速く、惹かれる気持ちを高められるのですか？', '["生理的な絆と安心感を生むから", "理性的な思考を通らないから", "支配力を示すから", "自信を証明するから"]'::jsonb, '触れることは、言葉だけでは生み出せない、信頼と絆の反応を呼び起こします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bd77420f-f0c3-434d-a194-ed4c67dc0f59', 'ja', '腕に軽く触れたあと、彼女が少し身を引きます。どうするべきですか？', '["スペースを空け、それ以上触れずに続ける", "自信を示すために、もう一度触れる", "謝って、次からは許可を求める", "別の触れ方に進む"]'::jsonb, '彼女の反応を尊重して、体の距離を縮めるのをいったん止めましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c23fa6ee-381a-4d27-bf59-41f86d51451f', 'ja', '彼女が、こちらを軽くからかって笑います。空気を少し変えるために、何と言えますか？', '["「笑うと、目がぱっと輝きますね。すてきだなと思って」", "「面白いですね」", "「うまいですね」", "「今回は、そちらの勝ちですね」"]'::jsonb, 'やわらかいトーンと具体的な観察は、重くならずに、惹かれていることをにじませます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c595ee3e-bb2d-4d31-8268-40919fdef131', 'ja', '彼女が、テニスでは負けず嫌いだと、遊び心を込めて自慢します。何と言えますか？', '["「それは、いつも良いこととは限りませんよ」", "「勝負は大好きです。こちらが勝っても、泣かないでくださいね」", "「競争は、体に良くないですよ」", "「それについて、もっと聞かせてください」"]'::jsonb, '彼女の遊び心に合わせて、軽い掛け合いとエネルギーを盛り上げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c98b4016-8474-4fa7-b00d-224a8135153a', 'ja', '声をかける前に、正しい心の持ち方を最もよく支える言葉は、どれですか？', '["「目立たなければ」", "「今夜は、いい思いができるかもしれない」", "「自信を持たなければ」", "「目指すのは、良い時間をつくることだ」"]'::jsonb, 'この心の持ち方は、地に足をつけ、その場にいて、プレッシャーのない状態を保たせてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cbbc6dae-7dab-4dde-93eb-57bc3de19179', 'ja', '軽い、遊びの勝負の使い方として、良くないのはどれですか？', '["彼女のコーヒーの注文を当てること", "2つの選択肢を比べて、どちらかを選んでもらうこと", "彼女の知らないことについて、クイズを出すこと", "質問を、遊び心のある当てっこに変えること"]'::jsonb, '勝負は、彼女が「自分は足りない」と感じるような立場に置くものであってはいけません。目指すのは、楽しむことです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cde2d207-7899-48ff-a104-fbf28135a2b2', 'ja', '距離が近づいても彼女が心地よく感じているサインは、どれですか？', '["こちらが近づいても、会話に乗ったままでいる", "身を寄せたり、こちらのほうへ体を向けたりする", "会話のあいだずっと、目を合わせたままでいる"]'::jsonb, '心地よさは、その場にとどまること、同じように返してくること、リラックスした関わり方に表れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ce4b3a53-6296-4e5e-9208-4ef8f7666fd8', 'ja', 'アイコンタクトをうまく使うのを支える考え方は、どれですか？', '["「彼女を感心させなければ」", "「気まずさは避けるべきだ」", "「見られていても、落ち着いていられる」", "「何か気の利いたことを言わなければ」"]'::jsonb, '緊張感を生むアイコンタクトは、うまく見せることからではなく、その場にいることへの落ち着きから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cebe76a8-b37d-42fc-a5ff-e7a9ecc85c3c', 'ja', 'バーで、ある女性と駆け引きを始めます。一番の目標は、何であるべきですか？', '["LINEを聞くか、今夜家に連れて帰ること", "今この瞬間に、楽しく心地よい時間をつくること", "褒め言葉と緊張感で、彼女を感心させること", "自信があり、ふさわしい相手だと証明すること"]'::jsonb, '駆け引きは、結果に関係なく、その時間がより軽やかで生き生きと感じられたとき、うまくいったと言えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1e81b89-292c-47d2-881c-2ead24b571e1', 'ja', '努力や表現についての褒め言葉は、なぜ見た目についての褒め言葉よりもうまくいくのですか？', '["より知的に感じられるから", "プレッシャーを減らし、よりその人に向けたものに感じられるから", "自分がより面白い人に見えるから", "言うのがより難しいから"]'::jsonb, '選択と努力に目を向けた褒め言葉は、より安心でき、つながりを感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5e4ef95-c1aa-4bd2-a5ca-49fc6afba2c8', 'ja', '人の関心を離れさせることがある行動は、どれですか？', '["どちらともつかないボディランゲージ", "簡単な質問をすること", "短い会話", "低く重いエネルギーを持ち込むこと"]'::jsonb, '人は、消耗させられるように感じる気分から、本能的に離れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d057ce-7c4d-495e-b2d7-fcc87a1c4105', 'ja', '彼女が「私、男性にはすごくうるさいんです」と言います。簡単にはなびかない返しとして、次に何と言えますか？', '["「いいことですね。そうあるべきですよ」", "「どんな人がタイプなんですか？」", "「その基準を満たせるように、がんばります」", "「ちょうどいいですね。こちらも、うるさいほうなので」"]'::jsonb, '遊び心のある切り返しは、承認を追いかけることなく、自分にも基準があることと、釣り合いを伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e7cbc051-5503-4e4c-b6fd-0a4dea2be140', 'ja', '彼女が、ある問題への独創的な解決策を話します。一番よく届く褒め言葉は、どれですか？', '["「すごくきれいですね」", "「それは、すごくうまいやり方ですね。思いつきませんでした」", "「すごく頭がいいんですね」", "「声に癒やされます」"]'::jsonb, '彼女の独創的な選択に目を向けた言葉で、その考え方を見てもらえたと感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e91466f0-24f3-4932-ab70-eab86651982c', 'ja', '早い段階の、相手に合わせたタッチで、一般的に無難な場所はどれですか？', '["前腕", "肩", "二の腕", "腰やヒップ"]'::jsonb, '早い段階のタッチは、親密すぎない場所にとどめ、その場の状況に合ったものにしましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea410aea-176d-48e3-8281-7a8a1353ca46', 'ja', '雰囲気はとても良いのですが、まだ触れ合ってはいません。彼女が、こちらの腕に軽く触れます。何ができますか？', '["気づかないふりをして、距離を保つ", "彼女が触れたことについて、ひと言言う", "すぐに、もっと彼女に触れる", "あとで、自然な瞬間に、軽いタッチで返す"]'::jsonb, 'お互いの心地よさに合うよう、彼女のサインに少しずつ合わせましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ebdbe221-f51b-4b0c-bd4b-aae266f0bcb8', 'ja', '話題の再登場は、なぜ惹かれる気持ちを高めるのですか？', '["支配力を示すから", "知性を示すから", "会話の労力を減らすから", "注意を払っていたことと、親しみを伝えるから"]'::jsonb, '覚えていてもらえると、人は「ちゃんと見てもらえている」と感じ、安心感とつながりが深まります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ec7b6208-0886-41d6-bcde-5876126e4cad', 'ja', 'アイコンタクトを、居心地の悪いものではなく、魅力的に感じさせる要素は、どれですか？', '["温かさ", "リラックスした姿勢", "落ち着いたペース", "食い入るように見つめ続けること"]'::jsonb, '緊張感は、プレッシャーからではなく、余裕と、その場にいる姿勢から生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('efb89d58-f624-4e43-8edf-0cee0dad7d5c', 'ja', '良いエネルギーの特徴は、どれですか？', '["温かい", "地に足がついている", "少しだけ明るい", "強烈で、支配的"]'::jsonb, '良いエネルギーは、相手を招き入れ、安心させるものです。圧倒したり、消耗させたりするものではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f23233f3-ec06-4834-bf59-d052a683bed7', 'ja', '言葉を使わずに、性的な緊張感を持ち込める行動は、どれですか？', '["ひと呼吸長く、目を合わせ続けること", "打ち解けてくるにつれて、少しだけ近くに立つこと", "流れを保つための、矢継ぎ早の質問", "彼女も同じように返しているとき、触れた手を少しだけそのままにすること"]'::jsonb, '感じのいい空気をさりげなく破る、言葉以外の合図が、可能性を持ち込みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f442e1ff-0765-4613-91d3-e838e3234d98', 'ja', '駆け引きにおける良いエネルギーとは、何ですか？', '["温かく、地に足のついたトーン", "相手を圧倒しない明るさ", "失敗を避けるための、平板でどちらともつかない態度", "その場の気分を、少しだけ上回ること"]'::jsonb, '良いエネルギーは、その場の空気を引き上げ、相手を生き生きとした気持ちにさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f5266e4f-abf4-4ecb-b84d-f1a01c78df7c', 'ja', '褒め言葉を、「感じがいい」から「惹かれている」へ、最も確実に変えるものは何ですか？', '["もっと強い言葉", "服装についての、もっと細かい内容", "トーン、アイコンタクト、ペース", "もっと大きな声で言うこと"]'::jsonb, '同じ言葉でも、伝え方によって、感じのいいひと言にも、熱のあるひと言にもなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f6cb6b9f-3832-422f-a15d-ba9827f8dbf8', 'ja', 'こちらが近づいたあと、彼女が少し下がります。次にどうするべきですか？', '["自信を示すために、もう一度近づく", "会話を終える", "居心地が悪いかどうかを尋ねる", "スペースをもっと空けて、落ち着いて続ける"]'::jsonb, '彼女の合図を尊重して元の距離に戻り、心地よさと信頼を保ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f6feba7a-6f51-4a47-b8a8-d65c8f9ea942', 'ja', '混み合った場所で、彼女を案内しています。ふさわしい触れ方はどれですか？', '["触れる必要はない", "肩に腕を回す", "導くために、腕に軽く触れる"]'::jsonb, '必要に応じた短い誘導は、その場の状況に合っていて、安心感を育てます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f798a3d2-77df-4e98-b5f6-850a383b86e9', 'ja', 'さりげないミラーリングは、なぜ効果的に打ち解けた空気を育てるのですか？', '["無意識のレベルで、安全と相性の良さを伝えるから", "なじみがあって信頼できる相手だと、彼女に感じさせるから", "似ていることを、言葉を使わずに伝えるから", "上のすべて"]'::jsonb, 'ミラーリングは、無意識のレベルで、親しみと心地よさを伝え、打ち解けるのを助けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7b1d87a-9566-45e6-a098-77d7a9c2ebaf', 'ja', '彼女が座り、こちらは彼女を見下ろす形で立っています。より良くミラーリングするために、何ができますか？', '["同じ高さになるよう、こちらも座っていいか尋ねる", "自信のある姿勢を保つために、立ったままでいる", "彼女の目の高さに合うよう、少しかがむ"]'::jsonb, '体の高さをそろえると、偏りが減り、無意識のうちに安心感が育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f7dc51a9-b997-4ed3-a54b-5996a6886069', 'ja', '人は、なぜ気分を引き上げてくれるエネルギーに、自然と引き寄せられるのですか？', '["温かい人は、もともと、より魅力的でカリスマ性があるから", "人は、自分の気持ちの状態を守るから。引き上げてくれるものを求め、消耗させるものを避ける", "引き込むエネルギーは、自信と社会的な立ち位置を伝えるから"]'::jsonb, '人は、心地よく感じるもののほうへ動き、そうでないものから離れます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fabb2d4d-834e-4aed-9716-9cafe7b3c118', 'ja', '彼女が、まっすぐ立っていた姿勢から、バーカウンターにもたれる姿勢に変えます。一番良い対応はどれですか？', '["まっすぐ立ったままでいる。あからさまなミラーリングは、気まずいから", "もたれているので、疲れているのかどうかを尋ねる", "自然に、こちらももたれる。彼女の大きな姿勢の変化を映す"]'::jsonb, 'さりげなくそろえることで、わざとらしさなしに、安心感が育ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fbd08cf5-bc99-4004-98d5-438bd2be4a9c', 'ja', '効果的なミラーリングの形は、どれですか？', '["彼女の姿勢や立ち方に合わせること", "小さな動きを、ひとつ残らず、すぐにまねること", "エネルギーとペースをそろえること", "声の大きさを、彼女に合わせて調整すること"]'::jsonb, 'ミラーリングは、無意識のレベルで、親しみと心地よさを伝え、打ち解けるのを助けます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
